"use client";

import { useState } from "react";
import { GamePlayers } from "./GamePlayers";
import { GameInventory } from "./GameInventory";
import { GameRoles } from "./GameRoles";

const SUB_TABS = [
  { key: "online", label: "Online Players" },
  { key: "inventory", label: "Inventory", mc: true },
  { key: "roles", label: "Roles & Permissions", mc: true },
] as const;

type SubKey = (typeof SUB_TABS)[number]["key"];

export function GamePlayersHub({
  serverId,
  running,
  playersMax,
  isMc,
}: {
  serverId: string;
  running: boolean;
  playersMax: number | null;
  isMc: boolean;
}) {
  const [sub, setSub] = useState<SubKey>("online");
  const visible = SUB_TABS.filter((t) => !t.mc || isMc);

  return (
    <div className="space-y-5">
      {/* Sub-tab pills — only render the bar when there are multiple tabs */}
      {visible.length > 1 && (
        <div className="flex flex-wrap gap-1.5">
          {visible.map((t) => {
            const active = sub === t.key;
            return (
              <button
                key={t.key}
                type="button"
                onClick={() => setSub(t.key)}
                className={`rounded-xl px-3.5 py-1.5 text-sm font-medium transition-colors ${
                  active
                    ? "bg-white/[0.08] text-white ring-1 ring-inset ring-brand-500/40"
                    : "text-slate-400 hover:bg-white/[0.04] hover:text-white"
                }`}
              >
                {t.label}
              </button>
            );
          })}
        </div>
      )}

      {sub === "online" && (
        <GamePlayers serverId={serverId} running={running} playersMax={playersMax} />
      )}
      {sub === "inventory" && isMc && (
        <GameInventory serverId={serverId} running={running} />
      )}
      {sub === "roles" && isMc && (
        <GameRoles serverId={serverId} running={running} />
      )}
    </div>
  );
}

